def write(path, text):
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(text, encoding='utf-8', newline='\n')

for tag, row in TEXT.items():
    values = row.split('|')
    assert len(values) == len(KEYS), (tag, len(values))
    qualifier = {'id': 'in', 'zh-Hans': 'b+zh+Hans', 'zh-Hant': 'b+zh+Hant'}.get(tag, tag)
    directory = 'values' if tag == 'en' else 'values-' + qualifier
    # Android's resource parser requires escaping literal apostrophes even in XML.
    body = '\n'.join(f'    <string name="{key}">{escape(value).replace(chr(39), chr(92)+chr(39))}</string>' for key, value in zip(KEYS, values))
    write(ROOT / 'companion/src/main/res' / directory / 'strings.xml', '<resources>\n    <string name="app_name" translatable="false">TAG Heuer McLaren Guide</string>\n' + body + '\n</resources>\n' if tag == 'en' else '<resources>\n' + body + '\n</resources>\n')
    if tag != 'en':
        wear_body = f'<resources>\n    <string name="accent_color">{escape(values[-1])}</string>\n</resources>\n'
        write(ROOT / 'wear/src/main/res' / directory / 'strings.xml', wear_body)

locales = '\n'.join(f'    <locale android:name="{tag}" />' for tag in TEXT)
write(ROOT / 'companion/src/main/res/xml/locales_config.xml', '<locale-config xmlns:android="http://schemas.android.com/apk/res/android">\n' + locales + '\n</locale-config>\n')
print(f'Generated {len(TEXT)} complete interface locales (English fallback for others).')
